package com.ecopassport.model; import jakarta.persistence.*; @Entity @Table(name="users") public class User{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String name; @Column(unique=true) String email; String password; String role="MANUFACTURER"; public User(){} public User(String n,String e,String p,String r){name=n;email=e;password=p;role=r;} public Long getId(){return id;} public String getName(){return name;} public String getEmail(){return email;} public String getPassword(){return password;} public String getRole(){return role;}}
